<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';
require_login();
require_once __DIR__ . '/includes/layout.php';
$credentials = read_admin_credentials(); $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { try { verify_csrf(); if (($credentials['source'] ?? '') === 'environment') throw new RuntimeException('بيانات الدخول مضبوطة عبر متغيرات البيئة ويجب تغييرها في إعداد الخادم.'); if (!password_verify(request_value('current_password'), (string)($credentials['password_hash'] ?? ''))) throw new RuntimeException('كلمة المرور الحالية غير صحيحة.'); if (request_value('new_password') !== request_value('confirm_password')) throw new RuntimeException('تأكيد كلمة المرور غير مطابق.'); save_admin_credentials(request_value('username'), request_value('new_password')); session_regenerate_id(true); set_flash('success','تم تحديث بيانات الدخول.'); redirect_to('settings.php'); } catch (Throwable $e) { $error = $e->getMessage(); } }
admin_header('الإعدادات', 'إدارة بيانات الدخول المحلية فقط'); if ($error !== ''): ?><div class="alert alert--error" role="alert"><?= e($error) ?></div><?php endif; ?>
<section class="panel"><div class="panel-header"><div><h2>بيانات المدير</h2><p>استخدم كلمة مرور فريدة لا تقل عن 12 حرفاً.</p></div></div><?php if (($credentials['source'] ?? '') === 'environment'): ?><div class="alert alert--success">المصدر: متغيرات البيئة. التعديل من الواجهة معطل لحماية إعداد الخادم.</div><?php else: ?><form method="post"><?= csrf_field() ?><div class="form-grid"><div class="field"><label for="username">اسم المستخدم</label><input id="username" name="username" type="text" autocomplete="username" value="<?= e((string)($credentials['username'] ?? '')) ?>" required></div><div class="field"><label for="current_password">كلمة المرور الحالية</label><input id="current_password" name="current_password" type="password" autocomplete="current-password" required></div><div class="field"><label for="new_password">كلمة المرور الجديدة</label><input id="new_password" name="new_password" type="password" autocomplete="new-password" minlength="12" required></div><div class="field"><label for="confirm_password">تأكيد كلمة المرور</label><input id="confirm_password" name="confirm_password" type="password" autocomplete="new-password" minlength="12" required></div></div><div class="form-actions"><button class="btn" type="submit">حفظ بيانات الدخول</button></div></form><?php endif; ?></section><?php admin_footer();
